218	  actor: Actor,
219	  input: RemoveMemberInput,
220	): Promise<Member> {
221	  assertOrgScope(actor, input.orgId);
222	
223	  const member = requireFound(
224	    await memberRepo.findMemberById(input.orgId, input.memberId),
225	    "Member",
226	    input.memberId,
227	  );
228	  assertCan(actor, "member:remove", memberResource(member));
229	
230	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
231	
232	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
233	
234	  await emit("member.removed", {
235	    ...actorEnvelope(actor),
236	    memberId: removed.id,
237	    userId: removed.userId,
