171	/**
172	 * Role changes carry two rules the permission matrix cannot express:
173	 * nobody may grant a role above their own, and the last owner may not be
174	 * demoted. Both are checked after `can()` has had its say.
175	 */
176	export async function updateMemberRole(
177	  actor: Actor,
178	  input: UpdateMemberRoleInput,
179	): Promise<Member> {
180	  assertOrgScope(actor, input.orgId);
181	
182	  const member = requireFound(
183	    await memberRepo.findMemberById(input.orgId, input.memberId),
184	    "Member",
185	    input.memberId,
186	  );
187	  assertCan(actor, "member:update_role", memberResource(member));
188	
189	  if (!hasRoleAtLeast(actor.role, input.role)) {
190	    throw new Error(
191	      `A ${actor.role} cannot grant the ${input.role} role`,
192	    );
193	  }
194	
195	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
196	
197	  const updated = await memberRepo.updateMemberRole(
198	    input.orgId,
199	    input.memberId,
200	    input.role,
201	  );
202	
203	  await emit("member.role_changed", {
204	    ...actorEnvelope(actor),
205	    memberId: updated.id,
206	    from: member.role,
207	    to: updated.role,
208	  });
209	
210	  return updated;
211	}
