417	/**
418	 * Maps thrown domain errors onto `AppErrorShape`.
419	 *
420	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
421	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
422	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
423	 * client. Everything funnels through `toAppError()` so one thrown class maps
424	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
425	 */
426	import { FeatureDisabledError } from "@/lib/feature-flags";
427	import { PermissionDeniedError } from "@/lib/permissions";
428	import { InvalidSlugError } from "@/lib/slug";
429	import { AlreadyArchivedError } from "@/lib/soft-delete";
430	import { TenantScopeError } from "@/lib/tenant";
431	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
432	import { ZodError, type ZodIssue } from "zod";
433	
434	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
435	  unauthorized: 401,
436	  forbidden: 403,
437	  not_found: 404,
438	  validation_failed: 422,
439	  conflict: 409,
440	  rate_limited: 429,
441	  plan_limit_exceeded: 402,
442	  tenant_scope_violation: 403,
443	  internal_error: 500,
444	};
445	
446	/** True for the error classes this module knows how to translate faithfully. */
447	export function isDomainError(error: unknown): boolean {
448	  return (
449	    error instanceof PermissionDeniedError ||
450	    error instanceof TenantScopeError ||
451	    error instanceof FeatureDisabledError ||
452	    error instanceof AlreadyArchivedError ||
453	    error instanceof InvalidSlugError ||
454	    error instanceof ZodError
455	  );
456	}
457	
458	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
459	export function fieldErrorsFromZod(
460	  error: ZodError,
461	): Readonly<Record<string, readonly string[]>> {
462	  const fields: Record<string, string[]> = {};
463	  for (const issue of error.issues as readonly ZodIssue[]) {
464	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
465	    (fields[key] ??= []).push(issue.message);
466	  }
467	  return fields;
468	}
469	
470	export function toAppError(error: unknown): AppErrorShape {
471	  if (error instanceof ZodError) {
472	    return {
473	      code: "validation_failed",
474	      message: "Please correct the highlighted fields.",
475	      fieldErrors: fieldErrorsFromZod(error),
476	    };
477	  }
478	
479	  if (error instanceof PermissionDeniedError) {
480	    return {
481	      code: "forbidden",
482	      message: error.message,
483	      meta: {
484	        action: error.action,
485	        resourceKind: error.decision.resourceKind,
486	        reason: error.decision.reason,
487	      },
488	    };
489	  }
490	
491	  if (error instanceof TenantScopeError) {
492	    return {
493	      code: "tenant_scope_violation",
494	      message: "That resource belongs to a different organization.",
495	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
496	    };
497	  }
498	
499	  if (error instanceof FeatureDisabledError) {
500	    return {
501	      code: "forbidden",
502	      message: error.message,
503	      meta: { flag: error.flag },
504	    };
505	  }
506	
507	  if (error instanceof AlreadyArchivedError) {
508	    return {
509	      code: "conflict",
510	      message: error.message,
511	      meta: { entity: error.entity, id: error.id },
512	    };
513	  }
514	
515	  if (error instanceof InvalidSlugError) {
516	    return {
517	      code: "validation_failed",
518	      message: error.message,
519	      fieldErrors: { slug: [error.message] },
520	      meta: { value: error.value },
521	    };
522	  }
523	
524	  return {
525	    code: "internal_error",
526	    message:
527	      error instanceof Error ? error.message : "Something went wrong. Try again.",
528	  };
529	}
