484	/**
485	 * In-process, typed publish/subscribe bus.
486	 *
487	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
488	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
489	 * every reactive concern `subscribe()`s at module init (see
490	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
491	 * throwing handler never fails the emit or the sibling handlers.
492	 */
493	
494	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
495	
496	const handlers = new Map<TaskflowEventType, HandlerSet>();
497	
498	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
499	
500	/** Registers a handler for one event type. Call the return value to detach. */
501	export function subscribe<K extends TaskflowEventType>(
502	  type: K,
503	  handler: EventHandler<K>,
504	): Unsubscribe {
505	  const set = handlers.get(type) ?? new Set();
506	  set.add(handler as EventHandler<TaskflowEventType>);
507	  handlers.set(type, set);
508	  return () => {
509	    set.delete(handler as EventHandler<TaskflowEventType>);
510	  };
511	}
512	
513	/** Registers a handler that detaches itself after the first delivery. */
514	export function subscribeOnce<K extends TaskflowEventType>(
515	  type: K,
516	  handler: EventHandler<K>,
517	): Unsubscribe {
518	  const off = subscribe(type, (payload) => {
519	    off();
520	    return handler(payload);
521	  });
522	  return off;
523	}
524	
525	/**
526	 * Publishes an event to every subscriber. Resolves once all handlers settle;
527	 * rejected handlers are reported to the error sinks, never rethrown.
528	 */
529	export async function emit<K extends TaskflowEventType>(
530	  type: K,
531	  payload: TaskflowEventPayload<K>,
532	): Promise<void> {
533	  const set = handlers.get(type);
534	  if (!set || set.size === 0) return;
535	
536	  const results = await Promise.allSettled(
537	    [...set].map(async (handler) => {
538	      await (handler as EventHandler<K>)(payload);
539	    }),
540	  );
541	
542	  for (const result of results) {
543	    if (result.status === "rejected") {
544	      reportHandlerError(type, result.reason);
545	    }
546	  }
547	}
548	
549	/** Fire-and-forget variant for call sites that must not await delivery. */
550	export function emitAndForget<K extends TaskflowEventType>(
551	  type: K,
552	  payload: TaskflowEventPayload<K>,
553	): void {
554	  void emit(type, payload).catch((error: unknown) => {
555	    reportHandlerError(type, error);
556	  });
557	}
558	
559	export function onHandlerError(
560	  sink: (type: TaskflowEventType, error: unknown) => void,
561	): Unsubscribe {
562	  errorSinks.add(sink);
563	  return () => {
564	    errorSinks.delete(sink);
565	  };
