/**
 * The recorded owner offers the workspace to another active member. Nothing
 * changes hands until the offered member accepts.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  await assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (pending) {
    if (!hasLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await handoverRepo.resolveHandover(orgId, pending.id, "expired", null);
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    toIsoTimestamp(now),
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: `${org.name} was offered to you. Accept to become its owner.`,
    href: "/settings/danger",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the previous one steps down, so the organization holds an owner at
 * every instant and the last-owner rule is never in play.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const handover = await requireOfferFor(actor, orgId);

  const incoming = await memberRepo.findMember(orgId, actor.userId);
  if (!incoming || incoming.status !== "active") {
    throw new OwnershipHandoverError("nothing_pending");
  }
  const outgoing = await memberRepo.findMember(orgId, org.ownerId);

  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
  }
  const updated = await orgRepo.updateOrgOwner(orgId, actor.userId);

  const outgoingSteppedDown =
    outgoing !== null && outgoing.id !== incoming.id && outgoing.role === "owner";
  if (outgoingSteppedDown) {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
  }

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  if (incoming.role !== "owner") {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: incoming.id,
      from: incoming.role,
      to: "owner",
    });
  }
  if (outgoingSteppedDown) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: outgoing.id,
      from: outgoing.role,
      to: "admin",
    });
  }
  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: org.ownerId,
    toUserId: actor.userId,
  });

  return updated;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const handover = await requireOfferFor(actor, orgId);
  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The offering owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  await assertRecordedOwner(actor, org);

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || hasLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** The open offer, visible to every member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || hasLapsed(pending, new Date())) return null;
  return pending;
}

/** An offer made at T is open before T + 7 days and lapsed from then on. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= new Date(handover.expiresAt).getTime();
}

/**
 * The offer `actor` may accept or decline. Anyone but the offered member is
 * told nothing is pending; the offered member learns when it has lapsed.
 */
async function requireOfferFor(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/**
 * Offering and withdrawing belong to the recorded owner alone — the member
 * `organizations.owner_id` names. Holding the owner role is not enough.
 */
async function assertRecordedOwner(
  actor: Actor,
  org: Organization,
): Promise<void> {
  const membership =
    org.ownerId === actor.userId
      ? await memberRepo.findMember(org.id, actor.userId)
      : null;
  if (membership !== null && membership.status === "active") return;

  throw new PermissionDeniedError("org:update", {
    allowed: false,
    action: "org:update",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}
