import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import * as billingService from "@/server/services/billing-service";
import * as activityService from "@/server/services/activity-service";
import * as notificationService from "@/server/services/notification-service";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("flows", async () => {
  const off = activityService.registerActivityListeners();
  const t = await createTenant("ho-flow");
  const id = t.org.id;
  const h = await orgService.initiateOwnershipHandover(t.actors.owner, id, t.userIds.viewer);
  expect(Date.parse(h.expiresAt) - Date.parse(h.createdAt)).toBe(7 * 864e5);
  expect((await orgService.getPendingOwnershipHandover(t.actors.member, id))?.id).toBe(h.id);
  const n = await notificationService.listNotifications(t.actors.viewer, { orgId: id, recipientId: t.userIds.viewer, unreadOnly: false, limit: 25, cursor: null });
  expect(n.items.map((x) => x.kind)).toEqual(["ownership_handover"]);
  await expect(orgService.initiateOwnershipHandover(t.actors.owner, id, t.userIds.admin)).rejects.toMatchObject({ reason: "pending_exists" });
  await expect(orgService.acceptOwnershipHandover(t.actors.admin, id)).rejects.toBeInstanceOf(OwnershipHandoverError);
  const org = await orgService.acceptOwnershipHandover(t.actors.viewer, id);
  expect(org.ownerId).toBe(t.userIds.viewer);
  expect((await memberRepo.findMember(id, t.userIds.owner))?.role).toBe("admin");
  expect((await memberRepo.findMember(id, t.userIds.viewer))?.role).toBe("owner");
  await expect(orgService.acceptOwnershipHandover(t.actors.viewer, id)).rejects.toMatchObject({ reason: "nothing_pending" });
  await expect(billingService.changePlan(t.actors.owner, { orgId: id, plan: "enterprise", interval: "monthly" })).rejects.toBeInstanceOf(PermissionDeniedError);
  await billingService.changePlan(t.actors.viewer, { orgId: id, plan: "enterprise", interval: "monthly" });
  const prev = await memberRepo.findMember(id, t.userIds.owner);
  await memberService.removeMember(t.actors.viewer, { orgId: id, memberId: prev!.id });
  const acts = await activityService.listActivity(t.actors.admin, { orgId: id, limit: 25, cursor: null } as never);
  console.log(acts.items.map((a) => [a.action, a.actorId === t.userIds.viewer, JSON.stringify(a.metadata)]));
  // expiry
  await orgService.initiateOwnershipHandover(t.actors.viewer, id, t.userIds.member);
  vi.useFakeTimers({ now: Date.now() + 7 * 864e5 + 5 });
  await expect(orgService.acceptOwnershipHandover(t.actors.member, id)).rejects.toMatchObject({ reason: "expired" });
  expect(await orgService.getPendingOwnershipHandover(t.actors.member, id)).toBeNull();
  await orgService.initiateOwnershipHandover(t.actors.viewer, id, t.userIds.admin);
  const adminM = await memberRepo.findMember(id, t.userIds.admin);
  await memberService.removeMember(t.actors.viewer, { orgId: id, memberId: adminM!.id });
  expect(await orgService.getPendingOwnershipHandover(t.actors.member, id)).toBeNull();
  await expect(orgService.initiateOwnershipHandover(t.actors.viewer, id, t.userIds.admin)).rejects.toThrow(/not found/);
  vi.useRealTimers();
  off();
});
EOF
